package br.com.weg.workshop.post.dto; import br.com.weg.workshop.post.domain.Post; import java.time.Instant; import java.util.UUID; public record PostResponse(UUID id,String title,String content,String image,UUID workshopId,UUID categoryId,String status,boolean highlight,Instant scheduledAt,Instant publishedAt,UUID createdBy,Instant createdAt,Instant updatedAt,long likeCount,boolean likedByMe){public static PostResponse from(Post p,long likes,boolean liked){return new PostResponse(p.getId(),p.getTitle(),p.getContent(),p.getImage(),p.getWorkshop()==null?null:p.getWorkshop().getId(),p.getCategory()==null?null:p.getCategory().getId(),p.getStatus().name(),p.isHighlight(),p.getScheduledAt(),p.getPublishedAt(),p.getCreatedBy().getId(),p.getCreatedAt(),p.getUpdatedAt(),likes,liked);}}
